<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
    <title>2048</title>
    <style>
        body {
            background-color: #1e1e1e;
            color: white;
            font-family: Arial, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
        }
        #score {
            margin-bottom: 20px;
            font-size: 24px;
        }
        #reset {
            padding: 10px 20px;
            font-size: 16px;
            margin-bottom: 20px;
            background-color: #333;
            border: none;
            color: white;
            cursor: pointer;
        }
        #board {
            display: grid;
            grid-template-columns: repeat(4, 80px);
            gap: 10px;
        }
        .tile {
            width: 80px;
            height: 80px;
            background-color: #333;
            color: white;
            font-weight: bold;
            text-align: center;
            line-height: 80px;
            border-radius: 8px;
            box-sizing: border-box;
        }
    </style>
</head>
<body>
<div id="score">Score: 0</div>
<button id="reset">Reset</button>
<div id="board"></div>
<script>
const game = {
    size: 4,
    _board: [],
    _score: 0,

    reset() {
        this._board = Array(this.size).fill().map(() => Array(this.size).fill(0));
        this.addRandomTile();
        this.addRandomTile();
        this._score = 0;
        this.updateDOM();
    },

    move(direction) {
        const originalBoardStr = JSON.stringify(this._board);

        let newBoard, scoreDelta = 0;

        if (direction === 'left') {
            newBoard = [];
            for (let row of this._board) {
                const { row: processedRow, delta } = this.slideAndMergeWithScore([...row]);
                newBoard.push(processedRow);
                scoreDelta += delta;
            }
        } else if (direction === 'right') {
            newBoard = [];
            for (let row of this._board) {
                const reversedRow = [...row].reverse();
                const { row: processedReversed, delta } = this.slideAndMergeWithScore(reversedRow);
                const processedRow = processedReversed.reverse();
                newBoard.push(processedRow);
                scoreDelta += delta;
            }
        } else if (direction === 'up') {
            let transposed = this.transpose(this._board);
            let processedTransposed = [];
            for (let row of transposed) {
                const { row: processedRow, delta } = this.slideAndMergeWithScore([...row]);
                processedTransposed.push(processedRow);
                scoreDelta += delta;
            }
            newBoard = this.transpose(processedTransposed);
        } else if (direction === 'down') {
            let transposed = this.transpose(this._board);
            let processedTransposed = [];
            for (let row of transposed) {
                const reversedRow = [...row].reverse();
                const { row: processedReversed, delta } = this.slideAndMergeWithScore(reversedRow);
                const processedRow = processedReversed.reverse();
                processedTransposed.push(processedRow);
                scoreDelta += delta;
            }
            newBoard = this.transpose(processedTransposed);
        }

        let changed = JSON.stringify(newBoard) !== originalBoardStr;

        if (changed) {
            this._board = newBoard.map(row => [...row]);
            this._score += scoreDelta;
            this.addRandomTile();
            this.updateDOM();
        }
        return changed;
    },

    slideAndMergeWithScore(arr) {
        let filtered = arr.filter(num => num !== 0);
        const result = [];
        let delta = 0;

        for (let i = 0; i < filtered.length;) {
            if (i + 1 < filtered.length && filtered[i] === filtered[i + 1]) {
                const value = filtered[i];
                result.push(value * 2);
                delta += value * 2;
                i += 2;
            } else {
                result.push(filtered[i]);
                i++;
            }
        }

        while (result.length < arr.length) {
            result.push(0);
        }

        return { row: result, delta };
    },

    transpose(matrix) {
        return matrix[0].map((_, colIndex) => matrix.map(row => row[colIndex]));
    },

    addRandomTile() {
        const empty = [];
        for (let y = 0; y < this.size; y++) {
            for (let x = 0; x < this.size; x++) {
                if (this._board[y][x] === 0) {
                    empty.push({x, y});
                }
            }
        }

        if (!empty.length) return;

        const {x, y} = empty[Math.floor(Math.random() * empty.length)];
        this._board[y][x] = Math.random() < 0.9 ? 2 : 4;
    },

    board() {
        return this._board.map(row => [...row]);
    },

    setBoard(arr) {
        if (arr.length !== this.size || arr.some(row => row.length !== this.size)) {
            throw new Error('Invalid board array');
        }
        this._board = arr.map(row => [...row]);
        this.updateDOM();
    },

    score() {
        return this._score;
    },

    updateDOM() {
        document.getElementById('score').textContent = `Score: ${this._score}`;
        const boardEl = document.getElementById('board');
        boardEl.innerHTML = '';
        for (let row of this._board) {
            for (let val of row) {
                const tile = document.createElement('div');
                tile.className = 'tile';
                tile.textContent = val !== 0 ? val : '';
                boardEl.appendChild(tile);
            }
        }
    },
};

window.game = game;

game.reset();

document.getElementById('reset').addEventListener('click', () => {
    game.reset();
});

document.addEventListener('keydown', (e) => {
    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
    e.preventDefault();
    const dir = e.key.replace('Arrow', '').toLowerCase();
    game.move(dir);
});
</script>
</body>
</html>
